def is_square(n):
    if n < 0:
        return False
    if n == 0:
        return True
    x = int(n**0.5)
    return x*x == n or (x+1)*(x+1) == n

def check_polynomial(a, b, c, limit=100):
    # Q(x) = x^3 + ax^2 + bx + c
    squares = []
    for n in range(-limit, limit + 1):
        val = n**3 + a*n**2 + b*n + c
        if is_square(val):
            squares.append(n)
    return squares

found_values = set()
for a in range(-10, 11):
    for b in range(-10, 11):
        for c in range(-10, 11):
            sqs = check_polynomial(a, b, c, limit=50)
            if len(sqs) == 2 and sqs == [0, 1]:
                # Found a candidate!
                # Q(0) = c, Q(1) = 1 + a + b + c
                q0 = c
                q1 = 1 + a + b + c
                if is_square(q0) and is_square(q1):
                    found_values.add(q0 * q1)

print(f"Found values: {sorted(list(found_values))}")

